    'bitch', 'cocks', 'dicks', 'fagot', 'faggy', 'fucks', 'niger', 'nigga', 'nigger',
    'pussy', 'shits', 'sluts', 'spick', 'titty', 'twats', 'whore', 'wanks', 'jizzy',
